/* ===================================================================
   RELATÓRIO EM PDF — compartilhado pelo formulário e pelo painel

   Este arquivo é carregado pelas duas páginas, para o relatório sair
   idêntico nas duas e para uma mudança de layout valer nos dois
   lugares. Depende de /vendor-jspdf.js, carregado antes dele.

   Traz o checklist (ITENS), as fontes e os logos embutidos, e o
   desenho do PDF.
   =================================================================== */

/* ===================================================================
   1. CHECKLIST DE SITUAÇÃO
   id, rótulo, explicação curta (opcional).
   =================================================================== */
const ITENS = [
  ["consultoria_contratada","Consultoria contratada",""],
  ["visita_yuri","Visita do Yuri","Consultor de desenvolvimento de mercado"],
  ["visita_guilherme","Visita do Guilherme",""],
  ["ja_tem_ap","Já tem agricultura de precisão",""],
  ["ja_tinha_analise_solo","Já tinha análise de solo",""],
  ["regulagem_pulverizador","Regulagem de pulverizador",""],
  ["coleta_analise_solo","Coleta de análise de solo",""],
  ["coleta_analise_nematoide","Coleta de análise de nematoide",""]
];


/* ===================================================================
   2. ARQUIVOS EMBUTIDOS
   Poppins (SIL Open Font License) nos quatro estilos usados pelo
   relatório, e os dois logos em branco. Ficam aqui dentro para o PDF
   sair igual mesmo sem internet.
   =================================================================== */
const FONTE_NORMAL = "";
const FONTE_ITALICO = "";
const FONTE_NEGRITO = "";
const FONTE_NEGRITO_ITALICO = "";
const LOGO_TF = "data:image/png;base64,";
const LOGO_FOC = "data:image/png;base64,";

/* ===================================================================
   3. RELATÓRIO EM PDF
   Desenhado por código, sem passar pela janela de impressão. As cores
   aqui são as do relatório (verde Terra Forte), independentes do azul
   da tela.
   =================================================================== */
const PDF_CORES = {
  verde:    [63, 95, 42],
  verdeMed: [82, 122, 56],
  tinta:    [31, 42, 28],
  fraca:    [106, 116, 114],
  linha:    [217, 206, 189],
  claro:    [200, 220, 192],
  branco:   [255, 255, 255]
};

const PDF = {
  margem: 14,
  largura: 182,
  fim: 275,      // altura máxima antes de virar a página
  linha: 4.7     // altura de uma linha de texto corrido
};

function registraFontes(doc) {
  doc.addFileToVFS("Poppins-400.ttf", FONTE_NORMAL);
  doc.addFont("Poppins-400.ttf", "Poppins", "normal");
  doc.addFileToVFS("Poppins-400i.ttf", FONTE_ITALICO);
  doc.addFont("Poppins-400i.ttf", "Poppins", "italic");
  doc.addFileToVFS("Poppins-600.ttf", FONTE_NEGRITO);
  doc.addFont("Poppins-600.ttf", "Poppins", "bold");
  doc.addFileToVFS("Poppins-600i.ttf", FONTE_NEGRITO_ITALICO);
  doc.addFont("Poppins-600i.ttf", "Poppins", "bolditalic");
  doc.setFont("Poppins", "normal");
}

/* --- o texto da descrição vem com marcações; vira blocos de trechos --- */
function blocosDeHtml(html) {
  const raiz = document.createElement("div");
  raiz.innerHTML = html || "";
  const blocos = [];
  let atual = null;

  const abre = tipo => { atual = { tipo, trechos: [] }; blocos.push(atual); };

  (function anda(no, est) {
    for (const n of no.childNodes) {
      if (n.nodeType === 3) {
        const t = n.nodeValue.replace(/\s+/g, " ");
        if (!t) continue;
        if (!atual) abre("p");
        atual.trechos.push({ t, ...est });
      } else if (n.nodeType === 1) {
        const tag = n.tagName;
        if (tag === "BR") { abre("p"); continue; }
        if (tag === "LI") { abre("li"); anda(n, est); atual = null; continue; }
        if (tag === "UL" || tag === "OL") { atual = null; anda(n, est); continue; }
        if (tag === "P" || tag === "DIV") { atual = null; anda(n, est); atual = null; continue; }
        anda(n, {
          negrito:    est.negrito    || tag === "B" || tag === "STRONG",
          italico:    est.italico    || tag === "I" || tag === "EM",
          sublinhado: est.sublinhado || tag === "U"
        });
      }
    }
  })(raiz, {});

  return blocos.filter(b => b.trechos.some(t => t.t.trim()));
}

function estilo(t) {
  if (t.negrito && t.italico) return "bolditalic";
  if (t.negrito) return "bold";
  if (t.italico) return "italic";
  return "normal";
}

/* separa os trechos em palavras, guardando quais colam na anterior
   (sem isso, um trecho que comeca com virgula ganharia um espaco antes) */
function palavrasDe(trechos) {
  const saida = [];
  let cola = true;          /* vale entre um trecho e o seguinte, por isso fica fora do laco */
  for (const trecho of trechos) {
    for (const pedaco of trecho.t.split(/(\s+)/)) {
      if (pedaco === "") continue;
      if (/^\s+$/.test(pedaco)) { cola = false; continue; }
      saida.push({ ...trecho, t: pedaco, cola });
      cola = true;
    }
  }
  return saida;
}

/* quebra os trechos de um bloco em linhas que caibam na largura */
function quebraEmLinhas(doc, trechos, largura) {
  const linhas = [];
  let linha = [], usado = 0;

  for (const palavra of palavrasDe(trechos)) {
    doc.setFont("Poppins", estilo(palavra));
    const texto = (usado === 0 || palavra.cola) ? palavra.t : " " + palavra.t;
    const larg = doc.getTextWidth(texto);

    if (usado > 0 && !palavra.cola && usado + larg > largura) {
      linhas.push(linha);
      linha = [{ ...palavra, t: palavra.t }];
      usado = doc.getTextWidth(palavra.t);
      continue;
    }
    const ultimo = linha[linha.length - 1];
    if (ultimo && estilo(ultimo) === estilo(palavra) && ultimo.sublinhado === palavra.sublinhado) {
      ultimo.t += texto;
    } else {
      linha.push({ ...palavra, t: texto });
    }
    usado += larg;
  }
  if (linha.length) linhas.push(linha);
  return linhas;
}

/* ------------------------------------------------------------------ */
function gerarPdf(r) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: "mm", format: "a4", compress: true });
  registraFontes(doc);

  const M = PDF.margem, L = PDF.largura, D = M + L;
  const br = d => d ? d.split("-").reverse().join("/") : "";
  let y;

  const cor = (c, tipo = "texto") => tipo === "texto"
    ? doc.setTextColor(c[0], c[1], c[2])
    : doc.setFillColor(c[0], c[1], c[2]);

  const vira = altura => {
    if (y + altura > PDF.fim) { doc.addPage(); y = 22; }
  };

  /* ---------- faixa do topo ---------- */
  cor(PDF_CORES.verde, "fundo");
  doc.roundedRect(M, 14, L, 22, 2.5, 2.5, "F");

  doc.setFont("Poppins", "bold").setFontSize(15);
  cor(PDF_CORES.branco);
  doc.text("Relatório de visita", M + 8, 27.5);

  const tf = { l: 26, a: 26 * 110 / 370 };
  const foc = { l: 30, a: 30 * 87 / 560 };
  const dirLogo = D - 8;
  doc.addImage(LOGO_FOC, "PNG", dirLogo - foc.l, 21 - foc.a / 2, foc.l, foc.a);
  doc.addImage(LOGO_TF, "PNG", dirLogo - foc.l - 4 - tf.l, 21 - tf.a / 2, tf.l, tf.a);

  doc.setFont("Poppins", "normal").setFontSize(7.5);
  cor(PDF_CORES.claro);
  doc.text("Programa de Focalização Syngenta", dirLogo, 31.5, { align: "right" });

  /* ---------- identificação ---------- */
  const campo = (rotulo, valor, x, topo) => {
    doc.setFont("Poppins", "normal").setFontSize(8);
    cor(PDF_CORES.fraca);
    doc.text(rotulo, x, topo);
    doc.setFont("Poppins", "bold").setFontSize(10.5);
    cor(PDF_CORES.tinta);
    doc.text(valor || "—", x, topo + 5.5);
  };

  const col = L / 3;
  campo("Produtor",   r.produtor,        M,           47);
  campo("Município",  r.municipio,       M + col,     47);
  campo("Data da visita", br(r.data_visita), M + 2 * col, 47);
  campo("Consultor responsável", r.consultor, M, 61);
  campo("Talhão / referência", r.talhao, M + col, 61);

  y = 72;
  doc.setDrawColor(...PDF_CORES.linha).setLineWidth(0.3);
  doc.line(M, y, D, y);
  y += 9;

  /* ---------- títulos e blocos ---------- */
  const titulo = t => {
    vira(12);
    doc.setFont("Poppins", "bold").setFontSize(8.5);
    cor(PDF_CORES.verde);
    doc.text(t, M, y);
    y += 5.5;
  };

  const paragrafo = (texto, vazio) => {
    doc.setFont("Poppins", "normal").setFontSize(10.5);
    cor(texto ? PDF_CORES.tinta : PDF_CORES.fraca);
    const linhas = doc.splitTextToSize(texto || vazio, L);
    for (const ln of linhas) {
      vira(PDF.linha);
      doc.text(ln, M, y);
      y += PDF.linha;
    }
    y += 3;
  };

  const rico = html => {
    const blocos = blocosDeHtml(html);
    if (!blocos.length) return paragrafo("", "Sem descrição.");
    doc.setFontSize(10.5);
    cor(PDF_CORES.tinta);
    for (const b of blocos) {
      const recuo = b.tipo === "li" ? 5 : 0;
      const linhas = quebraEmLinhas(doc, b.trechos, L - recuo);
      linhas.forEach((linha, i) => {
        vira(PDF.linha);
        if (b.tipo === "li" && i === 0) {
          cor(PDF_CORES.tinta, "fundo");
          doc.circle(M + 1.6, y - 1.1, 0.55, "F");
        }
        let x = M + recuo;
        for (const t of linha) {
          doc.setFont("Poppins", estilo(t));
          doc.text(t.t, x, y);
          const w = doc.getTextWidth(t.t);
          if (t.sublinhado) {
            doc.setLineWidth(0.25);
            doc.line(x, y + 0.8, x + w, y + 0.8);
          }
          x += w;
        }
        y += PDF.linha;
      });
      y += 1.2;
    }
    y += 2;
  };

  titulo("Descrição da visita");
  rico(r.descricao_html || (r.descricao ? escapaPdf(r.descricao) : ""));

  titulo(r.prazo_acao ? "Ação definida — prazo " + br(r.prazo_acao) : "Ação definida");
  paragrafo(r.acao, "Nenhuma ação registrada.");

  /* ---------- situação do produtor ---------- */
  if (r.situacao) {
    titulo("Situação do produtor");
    doc.setFont("Poppins", "normal").setFontSize(9.5);
    const metade = L / 2;
    const itens = ITENS.map(([id, rotulo]) => [!!r.situacao[id], rotulo]);
    const porColuna = Math.ceil(itens.length / 2);
    const topo = y;
    let maior = y;

    itens.forEach(([sim, rotulo], i) => {
      const coluna = Math.floor(i / porColuna);
      const linhaY = topo + (i % porColuna) * 5.6;
      const x = M + coluna * metade;
      if (sim) {
        doc.setDrawColor(...PDF_CORES.verdeMed).setLineWidth(0.6);
        doc.lines([[0.9, 1.1], [2.1, -2.6]], x + 0.4, linhaY - 1.4);
        cor(PDF_CORES.tinta);
      } else {
        doc.setDrawColor(...PDF_CORES.fraca).setLineWidth(0.6);
        doc.line(x + 0.4, linhaY - 1.2, x + 3.2, linhaY - 1.2);
        cor(PDF_CORES.fraca);
      }
      doc.text(rotulo, x + 5, linhaY);
      maior = Math.max(maior, linhaY);
    });
    y = maior + 8;
  }

  /* ---------- área Syngenta ---------- */
  if (r.area_manejo_ha !== undefined || r.area_experimental_ha !== undefined) {
    const ha = v => (v === null || v === undefined)
      ? "—" : v.toLocaleString("pt-BR") + " ha";
    titulo("Área Syngenta");
    vira(20);
    [["Manejo 100%", r.area_manejo_ha], ["Experimental", r.area_experimental_ha]]
      .forEach(([rotulo, valor], i) => {
        const x = M + i * 46;
        doc.setDrawColor(...PDF_CORES.linha).setLineWidth(0.3);
        doc.roundedRect(x, y - 1, 42, 15, 2, 2, "S");
        doc.setFont("Poppins", "normal").setFontSize(8);
        cor(PDF_CORES.fraca);
        doc.text(rotulo, x + 4, y + 4.5);
        doc.setFont("Poppins", "bold").setFontSize(12);
        cor(PDF_CORES.verde);
        doc.text(ha(valor), x + 4, y + 11);
      });
    y += 22;
  }

  /* ---------- fotos ---------- */
  if (r.fotos && r.fotos.length) {
    titulo("Registro fotográfico");
    const n = r.fotos.length;
    const colunas = n === 1 ? 1 : (n === 2 || n === 4) ? 2 : 3;
    const vao = 6;
    const larg = Math.min((L - vao * (colunas - 1)) / colunas, 110);
    let alturaLinha = 0;

    r.fotos.forEach((foto, i) => {
      const prop = doc.getImageProperties(foto.dados);
      const alt = Math.min(larg * prop.height / prop.width, 70);
      if (i % colunas === 0) { vira(alt + 4); alturaLinha = alt; }
      else alturaLinha = Math.max(alturaLinha, alt);
      doc.addImage(foto.dados, "JPEG", M + (i % colunas) * (larg + vao), y,
                   larg, alt, "foto" + i, "MEDIUM");
      if (i % colunas === colunas - 1 || i === n - 1) y += alturaLinha + 5;
    });
    y += 2;
  }

  /* ---------- rodapé ---------- */
  vira(14);
  y += 2;
  doc.setDrawColor(...PDF_CORES.linha).setLineWidth(0.3);
  doc.line(M, y, D, y);
  y += 5.5;
  doc.setFont("Poppins", "normal").setFontSize(7.5);
  cor(PDF_CORES.fraca);
  doc.text("Registrado por " + r.consultor + " em " + br(r.data_visita), M, y);
  doc.text("Emitido em " + new Date().toLocaleDateString("pt-BR"), D, y, { align: "right" });

  return doc;
}

function escapaPdf(t) {
  return t.replace(/&/g, "&amp;").replace(/</g, "&lt;")
          .replace(/\n/g, "<br>");
}

function nomeArquivo(r, extensao) {
  return "visita_" + r.data_visita + "_"
    + r.produtor.toLowerCase()
        .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
        .replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 40)
    + extensao;
}

function baixaArquivo(blob, nome) {
  const url = URL.createObjectURL(blob);
  const a = Object.assign(document.createElement("a"), { href: url, download: nome });
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 5000);
}

function baixaPdf(r) {
  try {
    baixaArquivo(gerarPdf(r).output("blob"), nomeArquivo(r, ".pdf"));
    return true;
  } catch (e) {
    console.error(e);
    return false;
  }
}
